// Express, vulnerable: any logged-in user can read any invoice
app.get('/api/invoices/:id', requireLogin, (req, res) => {
  const invoice = db.prepare('SELECT * FROM invoices WHERE id = ?')
                    .get(req.params.id)
  if (!invoice) return res.sendStatus(404)
  res.json(invoice)        // never asks: is this req.user's invoice?
})

// Express, fixed: the query itself is scoped to the requester
app.get('/api/invoices/:id', requireLogin, (req, res) => {
  const invoice = db.prepare(
      'SELECT * FROM invoices WHERE id = ? AND owner_id = ?')
    .get(req.params.id, req.user.id)     // user id from the session, not the client
  if (!invoice) return res.sendStatus(404)  // same answer: missing or not yours
  res.json(invoice)
})

