  const share = db.prepare(
    `SELECT doc_id FROM shares
      WHERE token = ? AND recipient_id = ? AND expires_at > ?`)
    .get(req.params.token, req.user.id, Date.now())
  if (!share) return res.sendStatus(404)
  res.sendFile(pathForDoc(share.doc_id))
})

