# Flask: vulnerable. Any logged-in user reaches an admin function.
@app.post("/v1/admin/users/<int:uid>/delete")
@login_required
def v1_delete_user(uid):
    delete_user(uid)
    return jsonify(deleted=uid)

# Flask: fixed. The server checks the role for this exact function.
def role_required(role):
    def deco(f):
        @wraps(f)
        def inner(*a, **kw):
            if g.user is None:
                abort(401)               # not logged in
            if g.user["role"] != role:
                abort(403)               # logged in, but not allowed
            return f(*a, **kw)
        return inner
    return deco

@app.post("/v2/admin/users/<int:uid>/delete")
@role_required("admin")
def v2_delete_user(uid):
    delete_user(uid)
    return jsonify(deleted=uid)

