# Flask, fixed: client sends an id; server checks the owner, then serves
# the name it stored itself, through send_from_directory
@app.get("/v2/download/<file_id>")
@login_required
def v2_download(file_id):
    rec = FILES.get(file_id)                      # server-side record
    if rec is None or rec["owner_id"] != g.user["id"]:
        abort(404)
    return send_from_directory(UPLOADS, rec["stored_name"])

