// Express, fixed: an allowlist of fields a user may edit about themselves
const EDITABLE = ['name', 'email']
app.patch('/api/users/me', requireLogin, (req, res) => {
  for (const key of EDITABLE)
    if (key in req.body) req.user[key] = String(req.body[key])
  saveUser(req.user)
  // and return an explicit view, not the whole record
  res.json({ id: req.user.id, name: req.user.name, email: req.user.email })
})

