// Express: one helper owns the tenant filter; handlers never see raw tables
function tenantDb(req) {
  const tenant = req.user.tenantId          // from the session, verified at login
  return {
    invoice: id => db.prepare(
      'SELECT * FROM invoices WHERE id = ? AND tenant_id = ?').get(id, tenant),
    invoices: () => db.prepare(
      'SELECT * FROM invoices WHERE tenant_id = ?').all(tenant),
  }
}

app.get('/api/invoices/:id', requireLogin, (req, res) => {
  const inv = tenantDb(req).invoice(req.params.id)
  if (!inv || !canRead(req.user, inv)) return res.sendStatus(404)
  res.json(inv)
})

