ACL = {"doc:readme": {"ana": {"read", "write"}, "bo": {"read"}}}
def acl_can(user, action, doc):
    return action in ACL.get(doc, {}).get(user, set())

ROLES = {"ana": {"editor"}, "bo": {"viewer"}}
PERMS = {"editor": {"read", "write"}, "viewer": {"read"}}
def rbac_can(user, action, doc):
    return any(action in PERMS[r] for r in ROLES.get(user, ()))

def abac_can(user, action, doc, env):
    return (action == "read" and user["dept"] == doc["dept"]
            and doc["classification"] != "secret" and 8 <= env["hour"] < 18)

TUPLES = {("doc:readme", "parent", "folder:A"),
          ("folder:A", "viewer", "group:eng#member"),
          ("group:eng", "member", "cy")}
def rebac_viewer(user, obj):
    for (o, rel, subj) in TUPLES:
        if o != obj:
            continue
        if rel in ("viewer", "owner") and subj == user:
            return True
        if rel == "viewer" and subj.endswith("#member"):
            if (subj.split("#")[0], "member", user) in TUPLES:
                return True
        if rel == "parent" and rebac_viewer(user, subj):
            return True
    return False

// The only place that says yes. Unknown action or no user: deny.
const RULES = {
  'doc:read':  (u, d) => !!d && d.tenant === u.tenant &&
                         (d.ownerId === u.id || u.role === 'admin'),
  'user:list': (u)    => u.role === 'admin',
}
function can(user, action, resource) {
  const rule = RULES[action]
  if (!user || !rule) return false
  return rule(user, resource) === true
}

// Enforcement: every route must declare its action to be reachable.
function authorize(action, load = () => undefined) {
  return (req, res, next) => {
    const resource = load(req)
    if (can(req.user, action, resource)) return next()
    log.warn({ event: 'authz_denied', user: req.user?.id ?? null, action, path: req.path })
    res.sendStatus(req.user ? 404 : 401)
  }
}

