# OPA / Rego: deny unless a rule says allow
package app.authz

default allow := false

allow if {
	input.action == "doc:read"
	input.resource.tenant == input.user.tenant
	input.resource.owner_id == input.user.id
}

allow if {
	input.action == "doc:read"
	input.user.role == "admin"
	input.resource.tenant == input.user.tenant
}

// Cedar: owners may edit their photos; nobody but the owner sees Private ones
permit (
  principal,
  action == Action::"editPhoto",
  resource
)
when { resource.owner == principal };

forbid (
  principal,
  action == Action::"viewPhoto",
  resource
)
when { resource.tags.contains("Private") }
unless { principal == resource.owner };

