]
const WHO = [undefined, 7, 9, 1]

test('authorization matrix', async () => {
  for (const [path, ...expected] of MATRIX) {
    for (const [i, user] of WHO.entries()) {
      const res = await request(app).get(path).set(user ? { 'x-test-user': String(user) } : {})
      expect([path, user, res.status]).toEqual([path, user, expected[i]])
    }
  }
})
